import os,re,collections
root='AlgebraicJacobian.lean'
def mod2path(m): return m.replace('.','/')+'.lean'
def path2mod(p): return p[:-5].replace('/','.')
imports=collections.defaultdict(list)
allfiles=set()
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    if '.lake' in dp: continue
    for f in fn:
        if f.endswith('.lean'): allfiles.add(os.path.join(dp,f))
def readimports(p):
    if not os.path.exists(p): return []
    out=[]
    for line in open(p, encoding='utf-8'):
        m=re.match(r'^import\s+(\S+)',line)
        if m and m.group(1).startswith('AlgebraicJacobian'): out.append(m.group(1))
    return out
seen=set()
stack=[root]
while stack:
    p=stack.pop()
    if p in seen: continue
    seen.add(p)
    for m in readimports(p):
        stack.append(mod2path(m))
reach = seen - {root}
unreach = sorted(allfiles - reach)
print("total files under AlgebraicJacobian/:", len(allfiles))
print("reachable:", len(reach & allfiles))
print("UNREACHABLE total:", len(unreach))
pic=[u for u in unreach if u.startswith('AlgebraicJacobian/Picard/')]
print("unreachable Picard count:", len(pic))
for u in pic: print("  ", os.path.basename(u))
oth=[u for u in unreach if not u.startswith('AlgebraicJacobian/Picard/')]
print("unreachable non-Picard count:", len(oth))
for u in oth: print("  ", u)
EOF
